  "Add {name}": "{name} شامل کریں",
  "Adding a Depth file, or a series while a Depth file is loaded, turns Show Depth on, and removing the last Depth file or its genome file turns Show Depth off; turning Show Depth off hides the drawn Depth track at once. A changed Legend title clears a Legend tab rename of the old title at once. The rest, and a Depth track from changed files, apply on Generate.": "گہرائی کی فائل شامل کرنے یا گہرائی کی فائل لوڈ ہونے کے دوران سیریز شامل کرنے سے چیک باکس “گہرائی دکھائیں” آن ہو جاتا ہے، اور آخری گہرائی کی فائل یا اس کی جینوم فائل ہٹانے سے یہ چیک باکس آف ہو جاتا ہے۔ چیک باکس “گہرائی دکھائیں” آف کرنے سے ڈرا کیا گیا گہرائی ٹریک فوراً چھپ جاتا ہے۔ لیجنڈ کا عنوان بدلنے سے ٹیب “لیجنڈ” پر پرانے عنوان کے لیے کی گئی نام کی تبدیلی فوراً صاف ہو جاتی ہے۔ باقی تبدیلیاں اور بدلی ہوئی فائلوں سے بننے والا گہرائی ٹریک بناتے وقت لاگو ہوتے ہیں۔",
  "Additional horizontal gap ratio between visible content bounds in each row on multi-record canvas. 0 makes row content touch. Default: 0.10 (horizontal only).": "ملٹی ریکارڈ کینوس پر ہر قطار میں نظر آنے والے حصوں کی حدود کے درمیان اضافی افقی فاصلے کی نسبت۔ 0 ہو تو قطار کے حصے ایک دوسرے کو چھوتے ہیں۔ طے شدہ: 0.10 (صرف افقی)۔",
  "Additional visible gap ratio between row content bounds in multi-record canvas. 0 makes rows touch by content bounds. Default: 0.05 (vertical only).": "ملٹی ریکارڈ کینوس پر قطاروں کے نظر آنے والے حصوں کی حدود کے درمیان اضافی نظر آنے والے فاصلے کی نسبت۔ 0 ہو تو قطاریں نظر آنے والے حصوں کی حدود پر ایک دوسرے کو چھوتی ہیں۔ طے شدہ: 0.05 (صرف عمودی)۔",
  "Adjacent pairs": "ملحقہ جوڑیاں",
  "Adjacent-row pairs (same position in each row)": "ملحقہ قطاروں کی جوڑیاں (ہر قطار میں وہی پوزیشن)",
  "Adjust axis stroke settings and the circular scale interval.": "محور کی آؤٹ لائن کی ترتیبات اور دائروی پیمانے کے وقفے کو ایڈجسٹ کریں۔",
  "Adjust axis stroke settings plus the linear scale bar or ruler style.": "محور کی آؤٹ لائن کی ترتیبات کے ساتھ لکیری پیمانے کی پٹی یا رولر کے انداز کو ایڈجسٹ کریں۔",
  "Adjust dinucleotide content/skew calculation parameters and GC/skew track sizing.": "ڈائی نیوکلیوٹائیڈ کی مقدار اور skew کے حساب کے پیرامیٹروں اور GC اور skew کے ٹریک کے سائز کو ایڈجسٹ کریں۔",
  "Adjust feature dimensions and the stroke color and width for feature blocks and intron lines.": "فیچر کے سائز، نیز فیچر بلاکوں اور انٹرون کی لکیروں کی آؤٹ لائن کے رنگ اور چوڑائی کو ایڈجسٹ کریں۔",
  "Adjust legend position and typography.": "لیجنڈ کی پوزیشن اور ٹائپوگرافی کو ایڈجسٹ کریں۔",
  "Adjust radius offset factors for circular labels.": "دائروی خاکے کے لیبلوں کے رداس آفسیٹ کے فیکٹروں کو ایڈجسٹ کریں۔",
  "Adjust the plot title and record-label text.": "گراف کے عنوان اور ریکارڈ لیبل کے متن کو ایڈجسٹ کریں۔",
