  "Advanced similarity group settings": "مماثلت کے گروپ کی ایڈوانسڈ ترتیبات",
  "After Apply": "لاگو کرنے کے بعد",
  "Align Similarity Group": "مماثلت کا گروپ سیدھ میں لائیں",
  "Align applies resolved targets immediately; ambiguity opens review. Review alignment options… lets you inspect or change anchors, Skip, and direction before applying.": "بٹن “سیدھ میں لائیں” متعین شدہ اہداف کو فوراً لاگو کرتا ہے؛ ابہام ہو تو جائزہ کھل جاتا ہے۔ بٹن “سیدھ کے آپشنوں کا جائزہ لیں…” لاگو کرنے سے پہلے اینکروں، “چھوڑ دیں” اور سمت کو جانچنے یا بدلنے دیتا ہے۔",
  "Align at feature": "فیچر پر سیدھ میں لائیں",
  "Align at feature cannot line up these records while Wrap Rows cuts a record into rows: it would move a cut record sideways, or line the others up with the feature of a cut record that it does not rotate. Only a complete circular record is aligned by rotation and can be wrapped. Turn Wrap Rows off, then use Align at feature.": "جب چیک باکس “قطاروں کی ریپنگ” کسی ریکارڈ کو قطاروں میں کاٹتا ہے تو بٹن “فیچر پر سیدھ میں لائیں” کے ذریعے ان ریکارڈوں کو سیدھ میں نہیں لایا جا سکتا: اس سے کٹا ہوا ریکارڈ افقی طور پر کھسک جائے گا یا باقی ریکارڈ اس کٹے ہوئے ریکارڈ کے فیچر کے مطابق سیدھ میں آئیں گے، جب کہ وہ ریکارڈ گھمایا نہیں جاتا۔ صرف مکمل دائروی ریکارڈ گھماؤ سے سیدھ میں لایا جاتا ہے اور ریپ کیا جا سکتا ہے۔ چیک باکس “قطاروں کی ریپنگ” سے نشان ہٹائیں، پھر بٹن “فیچر پر سیدھ میں لائیں” استعمال کریں۔",
  "Align at feature writes each record's start on its own File card, and these records share one File card (a file with several records). Click Generate Diagram, which gives each record its own File card, then use Align at feature again.": "بٹن “فیچر پر سیدھ میں لائیں” کے ذریعے ہر ریکارڈ کا آغاز اس کے اپنے فائل کارڈ پر لکھا جاتا ہے، اور یہ ریکارڈ ایک ہی فائل کارڈ میں شریک ہیں (کئی ریکارڈوں والی ایک فائل)۔ بٹن “خاکہ بنائیں” پر کلک کریں، جس سے ہر ریکارڈ کو اس کا اپنا فائل کارڈ ملتا ہے، پھر بٹن “فیچر پر سیدھ میں لائیں” دوبارہ استعمال کریں۔",
