  "Applies on Generate": "بناتے وقت لاگو ہوتا ہے",
  "Applies on Generate, except turning a GC content, GC skew or Depth row on or off, removing one, and Use custom stack, which apply at once. These still apply on Generate: turning on a row added since the last Generate, a row that was off when the Session was loaded, or a Depth row after a Depth file change; and Use custom stack after a Session load (except when turned off on a Linear Result drawn with it) or while the Region Annotation sets differ from those of the Result, with every track it would hide or show.": "بناتے وقت لاگو ہوتا ہے، سوائے GC کی مقدار، GC skew یا گہرائی کی قطار کو آن یا آف کرنے، اسے ہٹانے اور چیک باکس “حسب ضرورت اسٹیک استعمال کریں” کے، جو فوراً لاگو ہوتے ہیں۔ یہ اب بھی بناتے وقت لاگو ہوتے ہیں: آخری بار بنانے کے بعد شامل کی گئی قطار کو آن کرنا، ایسی قطار کو آن کرنا جو سیشن لوڈ ہوتے وقت آف تھی یا گہرائی کی فائل بدلنے کے بعد گہرائی کی قطار کو آن کرنا؛ اور سیشن لوڈ کرنے کے بعد چیک باکس “حسب ضرورت اسٹیک استعمال کریں” (سوائے اس کے کہ اسے لکیری خاکے کے نتیجے پر آف کیا گیا ہو جو اسی کے ساتھ بنایا گیا تھا) یا جب خطوں کی تشریحات کے سیٹ نتیجے کے سیٹ سے مختلف ہوں، ان تمام ٹریکوں کے ساتھ جنہیں یہ چھپائے یا دکھائے گا۔",
  "Applies the live circular track arrangement used while Custom Track Slots is off. Custom Track Slots inherit this preset when enabled.": "حسب ضرورت ٹریک سلاٹ آف ہونے پر دائروی خاکے میں استعمال ہونے والی موجودہ ٹریک ترتیب کو لاگو کرتا ہے۔ حسب ضرورت ٹریک سلاٹ فعال ہونے پر اس پری سیٹ کو وراثت میں لیتے ہیں۔",
