  "Auto embeds labels that fit and routes the rest externally. Embedded Only drops labels that need external placement. External Only keeps labels outside feature bodies.": "آپشن “خودکار” وہ لیبل اندر ایمبیڈ کرتا ہے جو فٹ ہو جائیں اور باقی کو باہر رکھتا ہے۔ آپشن “صرف ایمبیڈڈ” وہ لیبل خارج کر دیتا ہے جنہیں بیرونی جگہ درکار ہو۔ آپشن “صرف بیرونی” لیبلوں کو فیچروں کے جسم سے باہر رکھتا ہے۔",
  "Auto follows the track layout (Above or Features on axis: labels above; Below: labels below). Above Feature draws labels above features (and below negative-strand features when Separate Strands is on).": "آپشن “خودکار” ٹریک لے آؤٹ کی پیروی کرتا ہے (آپشن “اوپر” یا “فیچر محور پر”: لیبل اوپر؛ آپشن “نیچے”: لیبل نیچے)۔ آپشن “فیچر کے اوپر” لیبلوں کو فیچروں کے اوپر رکھتا ہے (اور جب چیک باکس “اسٹرینڈ الگ الگ کریں” منتخب ہو تو ریورس اسٹرینڈ کے فیچروں کے نیچے)۔",
  "Auto hides these fields throughout the diagram": "آپشن “خودکار” ان فیلڈوں کو پورے خاکے میں چھپاتا ہے",
  "Auto makes the CDSs that share a locus identifier one unit and every other CDS a unit of its own. CDS makes each CDS a unit. Locus makes each locus a unit and requires a locus identifier, such as /locus_tag, on every CDS.": "آپشن “خودکار” مشترک locus ID والے CDS کو ملا کر ایک یونٹ اور باقی ہر CDS کو الگ یونٹ بناتا ہے۔ آپشن “CDS” ہر CDS کو ایک یونٹ بناتا ہے۔ آپشن “Locus” ہر locus کو ایک یونٹ بناتا ہے اور ہر CDS پر locus ID، جیسے /locus_tag، ضروری ہے۔",
  "Auto runs threaded LOSAT when this browser supports it, and serial LOSAT otherwise. LOSATN task dc-megablast needs threaded LOSAT.": "آپشن “خودکار” تب تھریڈڈ LOSAT چلاتا ہے جب یہ براؤزر اسے معاونت دیتا ہو، ورنہ ترتیب وار LOSAT چلاتا ہے۔ ٹول LOSATN کے ٹاسک dc-megablast کے لیے تھریڈڈ LOSAT ضروری ہے۔",
