  "Custom stack geometry is active. Use the Dinucleotide content row width, or Reset to copy this value into the stack.": "حسب ضرورت اسٹیک کی جیومیٹری فعال ہے۔ قطار “ڈائی نیوکلیوٹائیڈ مقدار” کی چوڑائی استعمال کریں یا اس قدر کو اسٹیک میں کاپی کرنے کے لیے بٹن “ری سیٹ کریں” پر کلک کریں۔",
  "Custom stack geometry is active. Use the Dinucleotide skew row radius, or Reset to copy this value into the stack.": "حسب ضرورت اسٹیک کی جیومیٹری فعال ہے۔ قطار “ڈائی نیوکلیوٹائیڈ skew” کا رداس استعمال کریں یا اس قدر کو اسٹیک میں کاپی کرنے کے لیے بٹن “ری سیٹ کریں” پر کلک کریں۔",
  "Custom stack geometry is active. Use the Dinucleotide skew row width, or Reset to copy this value into the stack.": "حسب ضرورت اسٹیک کی جیومیٹری فعال ہے۔ قطار “ڈائی نیوکلیوٹائیڈ skew” کی چوڑائی استعمال کریں یا اس قدر کو اسٹیک میں کاپی کرنے کے لیے بٹن “ری سیٹ کریں” پر کلک کریں۔",
  "Custom stack geometry is active. Use the Features row width, or Reset to copy this value into the stack.": "حسب ضرورت اسٹیک کی جیومیٹری فعال ہے۔ قطار “فیچر” کی چوڑائی استعمال کریں یا اس قدر کو اسٹیک میں کاپی کرنے کے لیے بٹن “ری سیٹ کریں” پر کلک کریں۔",
