  "Dinucleotide used for this content/skew track, such as GC or AT.": "اس مقدار یا skew ٹریک کے لیے استعمال ہونے والا ڈائی نیوکلیوٹائیڈ، جس کی مثالیں GC اور AT ہیں۔",
