  "Draw each record over rows of this length. Leave the length empty for Auto, which chooses it from the longest record.": "ہر ریکارڈ کو اس لمبائی کی قطاروں میں ڈرا کریں۔ “خودکار” کے لیے لمبائی خالی چھوڑیں؛ تب یہ سب سے لمبے ریکارڈ سے چنی جاتی ہے۔",
  "Draw one circular pairwise comparison ring per uploaded BLAST outfmt 6/7 file or browser LOSATN/TLOSATX comparison sequence file (FASTA, GenBank, or DDBJ). Reverse BLAST coordinates are shown as reverse hits, not origin-spanning hits.": "ہر اپ لوڈ شدہ BLAST outfmt 6/7 فائل یا براؤزر میں LOSATN/TLOSATX کے موازنے کی سیکوئنس فائل (FASTA، GenBank یا DDBJ) کے لیے ایک دائروی جوڑی وار موازنہ حلقہ ڈرا کریں۔ ریورس BLAST محددات ریورس hit کے طور پر دکھائے جاتے ہیں، مبدا کو پار کرنے والے hit کے طور پر نہیں۔",
  "Draw records": "ریکارڈ ڈرا کریں",
  "Draw the comparison rings. Generate runs their comparisons only while this is on.": "موازنہ حلقے ڈرا کریں۔ بناتے وقت ان کے موازنے صرف تب چلتے ہیں جب یہ آن ہو۔",
  "Draw this record": "اس ریکارڈ کو ڈرا کریں",
