  "Drawings": "ڈرائنگیں",
  "Draws each label that the label priority names from the gene qualifier in italics, also after its text is edited. Other labels stay upright.": "ہر وہ لیبل ترچھا ڈرا کیا جاتا ہے جس کا نام سیکشن “qualifier کی ترجیح” کے مطابق gene qualifier سے آتا ہے، متن میں ترمیم کے بعد بھی۔ باقی لیبل سیدھے رہتے ہیں۔",
  "Duplicate": "نقل بنائیں",
