  "E-value": "E-value",
  "E-value ≤ {value}": "زیادہ سے زیادہ E-value: {value}",
  "Each file becomes one row of the new drawing. Untick a window to leave it out.": "ہر فائل نئی ڈرائنگ کی ایک قطار بن جاتی ہے۔ کسی ونڈو کو خارج کرنے کے لیے اس کا نشان ہٹائیں۔",
  "Each file is used for every record.": "ہر فائل ہر ریکارڈ کے لیے استعمال ہوتی ہے۔",
  "Each selected pair must join two different available records on adjacent rows, and appear once.": "ہر منتخب جوڑی کو ملحقہ قطاروں پر دو مختلف دستیاب ریکارڈوں کو جوڑنا چاہیے، اور وہ صرف ایک بار شامل ہونی چاہیے۔",
  "Each track counts the features one query finds in each window of every record, as a heatmap or a histogram. The query is a feature type (* for every type), with an optional qualifier, value regex and length range.": "ہر ٹریک ہر ریکارڈ کی ہر ونڈو میں ایک query سے ملنے والے فیچر گنتا ہے اور یہ گنتی ہیٹ میپ یا ہسٹوگرام کی شکل میں دکھاتا ہے۔ query میں فیچر کی قسم (تمام اقسام کے لیے *) متعین ہوتی ہے؛ qualifier، قدر کا ریگولر ایکسپریشن اور لمبائی کی رینج اختیاری ہیں۔",
  "Each wrapped row draws a ruler on its axis. Set Scale Style to Ruler (Ticks), or turn Wrap Rows off.": "ہر ریپ شدہ قطار اپنے محور پر رولر ڈرا کرتی ہے۔ فیلڈ “پیمانے کا انداز” کو آپشن “رولر (ٹک مارک)” پر سیٹ کریں یا چیک باکس “قطاروں کی ریپنگ” سے نشان ہٹائیں۔",
  "Edge kind": "ایج کی قسم",
  "Edit": "ترمیم کریں",
  "Edit Species / Strain…": "نوع اور اسٹرین میں ترمیم کریں…",
  "Edit feature visibility rule": "فیچر کی نمائش کے قاعدے میں ترمیم کریں",
  "Edit label text": "لیبل کے متن میں ترمیم کریں",
  "Edit pattern": "پیٹرن میں ترمیم کریں",
  "Edit record definition": "ریکارڈ کی تعریف میں ترمیم کریں",
  "Edit setting": "سیٹنگ میں ترمیم کریں",
  "Edit specific color rule": "رنگ کے مخصوص قاعدے میں ترمیم کریں",
  "Edit the explicit circular stack. Opening or closing this panel does not enable or alter the stack. Rows above Axis render outside and rows below Axis render inside.": "دائروی خاکے کے واضح اسٹیک میں ترمیم کریں۔ اس پینل کو کھولنے یا بند کرنے سے اسٹیک فعال یا تبدیل نہیں ہوتا۔ قطار “محور” سے اوپر کی قطاریں باہر اور اس سے نیچے کی قطاریں اندر ڈرا ہوتی ہیں۔",
  "Edit the explicit linear track stack. Opening or closing this panel does not enable or alter the stack. Arrows reorder within the current side; Row actions move rows across the boundary.": "لکیری خاکے کے واضح ٹریک اسٹیک میں ترمیم کریں۔ اس پینل کو کھولنے یا بند کرنے سے اسٹیک فعال یا تبدیل نہیں ہوتا۔ تیر موجودہ طرف کے اندر ترتیب بدلتے ہیں؛ مینو “قطار کی کارروائیاں” سے قطاریں حد کے پار منتقل کی جاتی ہیں۔",
  "Edit this record in its File card in the sidebar.": "اس ریکارڈ میں ترمیم سائیڈ بار میں اس کے فائل کارڈ میں کریں۔",
