  "Font size for the circular shared plot title. Only used when the title position is Top or Bottom.": "مشترکہ دائروی گراف کے عنوان کا فونٹ سائز۔ صرف تب استعمال ہوتا ہے جب عنوان کی پوزیشن آپشن “اوپر” یا “نیچے” پر ہو۔",
