  "Font {family} could not be prepared for the PDF. Its text is drawn in {substitute}.": "فونٹ {family} PDF کے لیے تیار نہیں کیا جا سکا۔ اس فونٹ کا متن فونٹ {substitute} میں ڈرا کیا گیا ہے۔",
  "Font {family} is not embedded in the PDF: its license (OS/2 fsType) does not allow embedding. Its text is drawn in {substitute}.": "فونٹ {family} PDF میں ایمبیڈ نہیں کیا گیا: اس کا لائسنس (OS/2 fsType) ایمبیڈ کرنے کی اجازت نہیں دیتا۔ اس فونٹ کا متن فونٹ {substitute} میں ڈرا کیا گیا ہے۔",
  "Font {family} is not embedded: its license (OS/2 fsType) does not allow embedding. The SVG shows it only where {family} is installed.": "فونٹ {family} ایمبیڈ نہیں کیا گیا: اس کا لائسنس (OS/2 fsType) ایمبیڈ کرنے کی اجازت نہیں دیتا۔ SVG میں یہ صرف وہیں نظر آتا ہے جہاں فونٹ {family} انسٹال ہو۔",
  "Fonts loaded in this page could not be prepared again for drawing. Load them again in Font, or choose another font.": "اس صفحے میں لوڈ کیے گئے فونٹ ڈرائنگ کے لیے دوبارہ تیار نہیں کیے جا سکے۔ انہیں سیکشن “فونٹ” میں دوبارہ لوڈ کریں یا کوئی دوسرا فونٹ چنیں۔",
