  "LOSAT E-values use the subject source file as the search database, without the query record when both records come from the same file.": "ٹول LOSAT کے E-value تلاش کے ڈیٹابیس کے طور پر subject ماخذ فائل استعمال کرتے ہیں، اور جب دونوں ریکارڈ ایک ہی فائل سے ہوں تو query ریکارڈ کو شامل نہیں کرتے۔",
