  "LOSAT Settings": "ٹول LOSAT کی ترتیبات",
  "LOSAT cache": "ٹول LOSAT کا کیش",
  "LOSAT cache: {count} saved value ({path}) could not be read and was dropped.": "کیش (LOSAT): محفوظ کی گئی {count} قدر ({path}) پڑھی نہیں جا سکی اور خارج کر دی گئی۔",
  "LOSAT cache: {count} saved values ({path}) could not be read and were dropped.": "کیش (LOSAT): محفوظ کی گئی {count} قدریں ({path}) پڑھی نہیں جا سکیں اور خارج کر دی گئیں۔",
  "LOSAT execution": "ٹول LOSAT کا عمل درآمد",
  "LOSAT parallel runs": "ٹول LOSAT کے متوازی رن",
  "LOSAT reported: {message}": "ٹول LOSAT نے بتایا: {message}",
  "LOSAT stopped the comparison search. Generating again with the same settings and inputs stops the same way; change what LOSAT names below, then Generate again.": "ٹول LOSAT نے موازنہ تلاش روک دی۔ انہی ترتیبات اور ان پٹوں کے ساتھ دوبارہ بنانے پر بھی یہ اسی طرح رکے گا؛ جس کا حوالہ LOSAT نیچے دیتا ہے اسے تبدیل کریں، پھر خاکہ دوبارہ بنائیں۔",
  "LOSAT stopped unexpectedly during the comparison search. Generating again with the same settings and inputs stops the same way; change the comparison settings or inputs, then Generate again.": "ٹول LOSAT موازنہ تلاش کے دوران غیر متوقع طور پر رک گیا۔ انہی ترتیبات اور ان پٹوں کے ساتھ دوبارہ بنانے پر بھی یہ اسی طرح رکے گا؛ موازنے کی ترتیبات یا ان پٹ تبدیل کریں، پھر خاکہ دوبارہ بنائیں۔",
  "LOSAT stopped unexpectedly in threaded execution. Select Serial or Auto execution, or change the comparison settings or inputs, then Generate again.": "ٹول LOSAT تھریڈڈ عمل درآمد میں غیر متوقع طور پر رک گیا۔ عمل درآمد کے لیے آپشن “ترتیب وار” یا آپشن “خودکار” منتخب کریں یا موازنے کی ترتیبات یا ان پٹ تبدیل کریں، پھر خاکہ دوبارہ بنائیں۔",
  "LOSAT stopped unexpectedly in threaded execution; Serial or Auto execution may run the search.": "ٹول LOSAT تھریڈڈ عمل درآمد میں غیر متوقع طور پر رک گیا؛ عمل درآمد کے آپشن “ترتیب وار” یا “خودکار” سے تلاش چل سکتی ہے۔",
  "LOSAT stopped unexpectedly.": "ٹول LOSAT غیر متوقع طور پر رک گیا۔",
  "LOSAT threads per run": "ٹول LOSAT کے ہر رن کے تھریڈ",
  "LOSAT total threads": "ٹول LOSAT کے کل تھریڈ",
  "LOSATN and TLOSATX E-values use one scale for each pair of genomes: a genome is the files whose records share a row, with every record of those files counted, drawn or not, so a crop, a window or a split into files does not change them. LOSATP E-values use the proteins of the subject genome as the database size, every protein of every record of its files, drawn or not, so a crop, a window or a split into files does not change them either. For a genome pair whose drawn records are each the whole of a one-record file, LOSAT keeps its own scale, which it adjusts for the length of a hit, so that pair's E-values differ slightly from those of the same genomes cropped. A genome pair whose search space is past the largest LOSAT reads is searched per file, with a warning.": "ٹول LOSATN اور TLOSATX کے E-value جینوموں کی ہر جوڑی کے لیے ایک ہی پیمانہ استعمال کرتے ہیں: جینوم سے مراد وہ فائلیں ہیں جن کے ریکارڈ ایک قطار میں ہوں، اور ان فائلوں کے ہر ریکارڈ کو گنا جاتا ہے، چاہے وہ ڈرا کیا گیا ہو یا نہیں، اس لیے تراش، ونڈو یا فائلوں میں تقسیم ان E-value کو نہیں بدلتی۔ ٹول LOSATP کے E-value ڈیٹابیس کے سائز کے طور پر subject جینوم کے پروٹین استعمال کرتے ہیں، یعنی اس کی فائلوں کے ہر ریکارڈ کا ہر پروٹین، چاہے وہ ریکارڈ ڈرا کیا گیا ہو یا نہیں، اس لیے تراش، ونڈو یا فائلوں میں تقسیم ان E-value کو بھی نہیں بدلتی۔ جینوموں کی ایسی جوڑی کے لیے جس کا ہر ڈرا کیا گیا ریکارڈ ایک ریکارڈ والی فائل کا پورا ریکارڈ ہو، LOSAT اپنا پیمانہ برقرار رکھتا ہے، جسے وہ hit کی لمبائی کے مطابق ایڈجسٹ کرتا ہے، اس لیے اس جوڑی کے E-value انہی جینوموں کی تراش شدہ صورت کے E-value سے قدرے مختلف ہوتے ہیں۔ جینوموں کی جس جوڑی کی سرچ اسپیس LOSAT کی پڑھ سکنے والی سب سے بڑی حد سے زیادہ ہو، اس میں تلاش فی فائل کی جاتی ہے، اور انتباہ دکھایا جاتا ہے۔",
  "LOSATN and TLOSATX similarity ring E-values use one scale for each ring: the reference genome is the files of the drawn records and the ring's genome is the files of that ring, with every record of those files counted, drawn or not, so a crop, the records drawn or a split into files does not change them. For a ring whose genome and the reference genome are each a one-record file, LOSAT keeps its own scale, which it adjusts for the length of a hit, so that ring's E-values differ slightly from those of the same genomes split into files. A ring whose search space is past the largest LOSAT reads is searched per file, with a warning.": "ٹول LOSATN اور TLOSATX کے مماثلت کے حلقوں کے E-value ہر حلقے کے لیے ایک ہی پیمانہ استعمال کرتے ہیں: ریفرنس جینوم سے مراد ڈرا کیے گئے ریکارڈوں کی فائلیں ہیں اور حلقے کے جینوم سے مراد اس حلقے کی فائلیں ہیں۔ ان فائلوں کا ہر ریکارڈ گنا جاتا ہے، چاہے وہ ڈرا کیا گیا ہو یا نہیں، اس لیے تراش، ڈرا کیے گئے ریکارڈ یا فائلوں میں تقسیم ان E-value کو نہیں بدلتی۔ جس حلقے کا جینوم اور ریفرنس جینوم ہر ایک ایک ریکارڈ والی فائل ہو، اس کے لیے LOSAT اپنا پیمانہ برقرار رکھتا ہے، جسے وہ hit کی لمبائی کے مطابق ایڈجسٹ کرتا ہے، اس لیے اس حلقے کے E-value انہی جینوموں کو فائلوں میں تقسیم کرنے پر حاصل ہونے والے E-value سے قدرے مختلف ہوتے ہیں۔ جس حلقے کی سرچ اسپیس LOSAT کی پڑھ سکنے والی سب سے بڑی حد سے زیادہ ہو، اس کے لیے انتباہ کے ساتھ ہر فائل میں الگ تلاش کی جاتی ہے۔",
  "LOSATN task": "ٹول LOSATN کا ٹاسک",
  "LOSATN task dc-megablast runs only with threaded LOSAT. Select Threaded or Auto under Execution in a browser where Threaded is available, or choose task megablast or blastn.": "ٹاسک dc-megablast (LOSATN) صرف تھریڈڈ LOSAT کے ساتھ چلتا ہے۔ ایسے براؤزر میں جہاں آپشن “تھریڈڈ” دستیاب ہو، فیلڈ “عمل درآمد” کے تحت آپشن “تھریڈڈ” یا “خودکار” منتخب کریں یا ٹاسک megablast یا blastn چنیں۔",
  "LOSATP Max target seqs": "ٹول LOSATP کی زیادہ سے زیادہ ہدف سیکوئنس",
  "LOSATP mode": "ٹول LOSATP کا موڈ",
