  "Label fewer features: Blacklist or Whitelist under LABEL FILTERING.": "کم فیچروں پر لیبل لگائیں: سیکشن “لیبل فلٹرنگ” میں بلیک لسٹ یا وائٹ لسٹ استعمال کریں۔",
