  "Label visibility is On for a feature, but this diagram does not draw its label.": "کسی فیچر کے لیے فیلڈ “لیبل کی نمائش” کی قدر “آن” ہے، لیکن یہ خاکہ اس کا لیبل ڈرا نہیں کرتا۔",
  "Label visibility: Default follows Show Labels and the label filters": "لیبل کی نمائش: آپشن “طے شدہ” سیٹنگ “لیبل دکھائیں” اور لیبل فلٹروں کی پیروی کرتا ہے",
  "Label whitelist": "لیبل وائٹ لسٹ",
  "Labels": "لیبل",
  "Labels are not drawn for features drawn as \"Underlay\".": "جن فیچروں کو “انڈر لے” کے طور پر ڈرا کیا گیا ہو ان کے لیبل ڈرا نہیں کیے جاتے۔",
  "Labels are not drawn on {type} features, because Feature Types draws them as Underlay.": "فیچر {type} پر لیبل ڈرا نہیں کیے جاتے، کیونکہ سیکشن “فیچر کی اقسام” ان فیچروں کو آپشن “انڈر لے” کے طور پر ڈرا کرتا ہے۔",
  "Labels are set to \"None\" (\"Show Labels\" or \"Label Mode\"), so only a feature with Label visibility \"On\" has one.": "سیٹنگ “لیبل دکھائیں” یا “لیبل موڈ” کی قدر “کوئی نہیں” ہے، اس لیے صرف اسی فیچر کا لیبل دکھایا جاتا ہے جس کے فیلڈ “لیبل کی نمائش” کی قدر “آن” ہو۔",
