  "Legend: entries {items} had a color the app does not accept and were dropped.": "لیجنڈ: آئٹموں {items} میں ایسے رنگ تھے جنہیں ایپ قبول نہیں کرتی، اس لیے یہ آئٹم خارج کر دیے گئے۔",
  "Legend: entries {items} repeat an earlier entry of their list and were dropped.": "لیجنڈ: آئٹم {items} اپنی فہرست میں پہلے سے موجود کسی آئٹم کی تکرار ہیں، اس لیے یہ آئٹم خارج کر دیے گئے۔",
  "Legend: entry {items} had a color the app does not accept and was dropped.": "لیجنڈ: آئٹم {items} میں ایسا رنگ تھا جسے ایپ قبول نہیں کرتی، اس لیے یہ آئٹم خارج کر دیا گیا۔",
  "Legend: entry {items} repeats an earlier entry of its list and was dropped.": "لیجنڈ: آئٹم {items} اپنی فہرست میں پہلے سے موجود ایک آئٹم کی تکرار ہے، اس لیے یہ آئٹم خارج کر دیا گیا۔",
  "Legend: the color edit stored under \"{label}\" ({path}) moves to the row \"{used}\", which has an edit of its own; that edit is used and this one was dropped.": "لیجنڈ: لیجنڈ آئٹم “{label}” کے تحت رنگ کی محفوظ ترمیم ({path}) لیجنڈ قطار “{used}” پر منتقل ہوتی ہے جس کی اپنی الگ ترمیم موجود ہے؛ وہ ترمیم استعمال کی جاتی ہے اور یہ ترمیم خارج کر دی گئی۔",
  "Legend: the color edit stored under \"{label}\" ({path}) sets the row \"{used}\", which a later edit also sets; the later edit is used and this one was dropped.": "لیجنڈ: لیجنڈ آئٹم “{label}” کے تحت رنگ کی محفوظ ترمیم ({path}) لیجنڈ قطار “{used}” کو متعین کرتی ہے، جسے بعد کی ایک ترمیم بھی متعین کرتی ہے؛ بعد کی ترمیم استعمال کی جاتی ہے اور یہ ترمیم خارج کر دی گئی۔",
  "Legend: the entry stored under \"{label}\" ({path}) moves to the row \"{used}\", which has an entry of its own; that entry is used and this one was dropped.": "لیجنڈ: لیجنڈ آئٹم “{label}” کے تحت محفوظ آئٹم ({path}) لیجنڈ قطار “{used}” پر منتقل ہوتا ہے جس کا اپنا الگ آئٹم موجود ہے؛ وہ آئٹم استعمال کیا جاتا ہے اور یہ آئٹم خارج کر دیا گیا۔",
  "Legend: the entry stored under \"{label}\" ({path}) sets the row \"{used}\", which a later edit also sets; the later edit is used and this one was dropped.": "لیجنڈ: لیجنڈ آئٹم “{label}” کے تحت محفوظ آئٹم ({path}) لیجنڈ قطار “{used}” کو متعین کرتا ہے، جسے بعد کی ایک ترمیم بھی متعین کرتی ہے؛ بعد کی ترمیم استعمال کی جاتی ہے اور یہ آئٹم خارج کر دیا گیا۔",
  "Legend: the position \"{stored}\" ({path}) is not one of its mode's positions; it is not used.": "لیجنڈ: پوزیشن “{stored}” ({path}) اس کے موڈ کی پوزیشنوں میں شامل نہیں؛ اسے استعمال نہیں کیا جاتا۔",
  "Legend: the position \"{stored}\" ({path}) is not one of its mode's positions; {used} is used.": "لیجنڈ: پوزیشن “{stored}” ({path}) اس کے موڈ کی پوزیشنوں میں شامل نہیں؛ پوزیشن {used} استعمال کی جاتی ہے۔",
  "Legend: the stroke edit stored under \"{label}\" ({path}) moves to the row \"{used}\", which has an edit of its own; that edit is used and this one was dropped.": "لیجنڈ: لیجنڈ آئٹم “{label}” کے تحت آؤٹ لائن کی محفوظ ترمیم ({path}) لیجنڈ قطار “{used}” پر منتقل ہوتی ہے جس کی اپنی الگ ترمیم موجود ہے؛ وہ ترمیم استعمال کی جاتی ہے اور یہ ترمیم خارج کر دی گئی۔",
  "Legend: the stroke edit stored under \"{label}\" ({path}) sets the row \"{used}\", which a later edit also sets; the later edit is used and this one was dropped.": "لیجنڈ: لیجنڈ آئٹم “{label}” کے تحت آؤٹ لائن کی محفوظ ترمیم ({path}) لیجنڈ قطار “{used}” کو متعین کرتی ہے، جسے بعد کی ایک ترمیم بھی متعین کرتی ہے؛ بعد کی ترمیم استعمال کی جاتی ہے اور یہ ترمیم خارج کر دی گئی۔",
