  "Linear vertical spacing after the track, in pixels (px optional; nonnegative). Leave blank for the automatic spacing.": "ٹریک کے بعد لکیری خاکے کا عمودی فاصلہ، پکسل میں (px اختیاری؛ غیر منفی عدد)۔ خودکار فاصلے کے لیے خالی چھوڑیں۔",
  "Link Linear scale and ruler label font sizes": "لکیری پیمانے اور رولر کے لیبل کے فونٹ سائزوں کو منسلک کریں",
  "Link Scale and Ruler Label Font Sizes": "پیمانے اور رولر کے لیبل کے فونٹ سائز منسلک کریں",
  "Live edit applying: geometry is being updated. Direct edits already applied are kept.": "لائیو ترمیم لاگو ہو رہی ہے: جیومیٹری اپ ڈیٹ کی جا رہی ہے۔ پہلے سے لاگو براہ راست ترامیم برقرار رہتی ہیں۔",
  "Live edit failed: direct edits already applied are kept; geometry may still need updating.": "لائیو ترمیم ناکام ہو گئی: پہلے سے لاگو کی گئی براہ راست ترامیم برقرار ہیں؛ جیومیٹری کو اب بھی اپ ڈیٹ کرنے کی ضرورت ہو سکتی ہے۔",
  "Live edit. Showing a track applies on Generate if the Result did not draw it when its Session was loaded; after a Depth file or series change, or a change of the records the Depth files map to; for a custom stack row added since the last Generate or a stack the last Generate could not build; and, with a Circular custom track stack or Circular track widths or radii, when Hide GC Content or Hide GC Skew is turned off.": "لائیو ترمیم۔ ٹریک دکھانا بناتے وقت لاگو ہوتا ہے، اگر نتیجے میں سیشن لوڈ ہوتے وقت اسے ڈرا نہ کیا گیا ہو؛ گہرائی کی فائل یا سیریز بدلنے کے بعد یا ان ریکارڈوں کے بدلنے کے بعد جن سے گہرائی کی فائلیں منسلک ہیں؛ حسب ضرورت اسٹیک کی ایسی قطار کے لیے جو آخری بار بنانے کے بعد شامل کی گئی ہو یا ایسے اسٹیک کے لیے جسے آخری بار بناتے وقت تعمیر نہ کیا جا سکا؛ اور دائروی خاکے کے حسب ضرورت ٹریک اسٹیک یا دائروی خاکے کے ٹریک کی چوڑائیوں یا رداس کے ساتھ، جب چیک باکس “GC کی مقدار چھپائیں” یا چیک باکس “GC skew چھپائیں” آف کیا جائے۔",
  "Live edit: feature color, label text, and visibility update the current Result; geometry may rerender automatically.": "لائیو ترمیم: فیچر کا رنگ، لیبل کا متن اور نمائش موجودہ نتیجے کو اپ ڈیٹ کرتے ہیں؛ جیومیٹری خودکار طور پر دوبارہ رینڈر ہو سکتی ہے۔",
  "Live edit: legend text, order, stroke, and removal update the current Result.": "لائیو ترمیم: لیجنڈ کا متن، ترتیب، آؤٹ لائن اور ہٹانا موجودہ نتیجے کو اپ ڈیٹ کرتے ہیں۔",
  "Live edit: the padding updates the current Result.": "لائیو ترمیم: پیڈنگ موجودہ نتیجے کو اپ ڈیٹ کرتی ہے۔",
  "Live edit; the position applies on Generate after the Multi-Record Canvas change.": "لائیو ترمیم؛ سیٹنگ “ملٹی ریکارڈ کینوس” میں تبدیلی کے بعد پوزیشن بناتے وقت لاگو ہوتی ہے۔",
  "Live edit; the position applies on Generate after the One circle change.": "لائیو ترمیم؛ سیٹنگ “ایک دائرہ” میں تبدیلی کے بعد پوزیشن بناتے وقت لاگو ہوتی ہے۔",
