  "Make the figure larger: Figure width about {width}, Figure height about {height} (Figure size in Layout).": "شکل بڑی کریں: فیلڈ “شکل کی چوڑائی” کی قدر تقریباً {width}، فیلڈ “شکل کی اونچائی” کی قدر تقریباً {height} (سیکشن “لے آؤٹ” میں “شکل کا سائز”)۔",
  "Make the figure larger: increase Figure height (Figure size in Layout).": "شکل بڑی کریں: فیلڈ “شکل کی اونچائی” کی قدر بڑھائیں (سیکشن “لے آؤٹ” میں “شکل کا سائز”)۔",
  "Make the figure larger: increase Figure width (Figure size in Layout).": "شکل بڑی کریں: فیلڈ “شکل کی چوڑائی” کی قدر بڑھائیں (سیکشن “لے آؤٹ” میں “شکل کا سائز”)۔",
  "Make the figure larger: increase Figure width and Figure height (Figure size in Layout).": "شکل بڑی کریں: فیلڈ “شکل کی چوڑائی” اور فیلڈ “شکل کی اونچائی” کی قدریں بڑھائیں (سیکشن “لے آؤٹ” میں “شکل کا سائز”)۔",
  "Manual order and row assignment for multi-record canvas. Use Up/Down for left-to-right order within each row.": "ملٹی ریکارڈ کینوس کے لیے دستی ترتیب اور قطار کی تفویض۔ ہر قطار میں بائیں سے دائیں ترتیب کے لیے بٹن “اوپر” اور “نیچے” استعمال کریں۔",
  "Manual scale interval for circular mode (in bp; must be > 0). Overrides automatic calculation.": "دائروی موڈ کے لیے پیمانے کا دستی وقفہ (bp میں؛ 0 سے بڑا ہونا ضروری ہے)۔ یہ خودکار حساب کو اوور رائیڈ کرتا ہے۔",
  "Manual tick interval for Ruler scale style in bp (must be > 0). Leave blank to calculate automatically.": "پیمانے کے انداز “رولر” کے لیے ٹک مارک کا دستی وقفہ bp میں (0 سے بڑا ہونا ضروری ہے)۔ خودکار حساب کے لیے خالی چھوڑیں۔",
  "Marks": "نشانات",
  "Match depth references to the selected record.": "گہرائی کی ریفرنس سیکوئنسوں کو منتخب ریکارڈ سے مطابقت میں لائیں۔",
