  "Matched {detail}": "مطابقت: {detail}",
  "Max hits per protein for groups": "گروپوں کے لیے ہر پروٹین کے زیادہ سے زیادہ hit",
  "Max target seqs": "زیادہ سے زیادہ ہدف سیکوئنس",
  "Max unit gap": "یونٹ کا زیادہ سے زیادہ فاصلہ",
  "Maximum GC percentage for percent-mode clipping and axis scaling.": "فیصد موڈ میں کلپنگ اور محور کے پیمانے کے لیے GC کا زیادہ سے زیادہ فیصد۔",
  "Maximum depth for clipping and normalization. Leave blank for auto.": "کلپنگ اور نارملائزیشن کے لیے زیادہ سے زیادہ گہرائی۔ خودکار قدر کے لیے خالی چھوڑیں۔",
  "Maximum distinct subject proteins, not counting the protein itself, kept per query protein in each directed record-pair search to construct Similarity groups and Collinear blocks after result filtering. Leave blank to keep all hits passing the result filters. This does not limit raw LOSATP candidates or Pairwise display matches.": "نتیجے کے فلٹر کے بعد، مماثلت کے گروپ اور collinear بلاک بنانے کے لیے، ریکارڈوں کی ہر جوڑی کی ہر سمت دار تلاش میں ہر query پروٹین کے لیے رکھے جانے والے الگ subject پروٹینوں کی زیادہ سے زیادہ تعداد، خود پروٹین کو شمار کیے بغیر۔ نتیجے کے فلٹروں پر پورا اترنے والے تمام hit رکھنے کے لیے خالی چھوڑیں۔ اس سے LOSATP کے خام امیدواروں کی تعداد یا جوڑی وار ڈسپلے کی مطابقتوں کی تعداد محدود نہیں ہوتی۔",
  "Maximum filtered matches displayed per query protein in Pairwise mode. This does not limit LOSATP candidates or Similarity/Collinear member evidence.": "موڈ “جوڑی وار مطابقتیں” میں ہر query پروٹین کے لیے دکھائی جانے والی فلٹر شدہ مطابقتوں کی زیادہ سے زیادہ تعداد۔ اس سے LOSATP کے امیدواروں کی تعداد یا مماثلت کے گروپوں اور collinear بلاکوں کے ارکان کے شواہد محدود نہیں ہوتے۔",
  "Maximum number of units (loci, or CDSs without a locus identifier; see Unit mode) between neighboring anchors of one block, on both records. 0 joins adjacent units only. With Diagonal drift 0, a gap is bridged only when both records skip the same number of units.": "ایک بلاک کے پڑوسی اینکروں کے درمیان، دونوں ریکارڈوں پر، یونٹوں کی زیادہ سے زیادہ تعداد (loci یا locus ID کے بغیر CDS؛ فیلڈ “یونٹ موڈ” دیکھیں)۔ 0 ہو تو صرف ملحقہ یونٹ جڑتے ہیں۔ فیلڈ “ڈائیگنل ڈرفٹ” کی قدر 0 ہو تو فاصلہ صرف تب پار ہوتا ہے جب دونوں ریکارڈ یونٹوں کی ایک ہی تعداد چھوڑیں۔",
