  "Move the track, reduce widths, disable conflicting labels, or place it on the other side of the Axis.": "ٹریک منتقل کریں، چوڑائیاں کم کریں، ٹکرانے والے لیبل غیر فعال کریں یا ٹریک کو “محور” کی دوسری طرف رکھیں۔",
