  "Multi-Record Canvas": "ملٹی ریکارڈ کینوس",
  "Multi-Record Canvas uses a grid. Turn it off to select one record.": "اگر چیک باکس “ملٹی ریکارڈ کینوس” منتخب ہو تو گرڈ استعمال ہوتا ہے۔ ایک ریکارڈ منتخب کرنے کے لیے اس چیک باکس کا نشان ہٹائیں۔",
  "Name": "نام",
  "Name / Species": "نام / نوع",
  "Name of the Depth series this row draws. Typing renames the series everywhere: its series card, every row that draws it, and the legend. Leave blank for the default name: Depth, or Depth N when there are several series.": "گہرائی کی اس سیریز کا نام جسے یہ قطار ڈرا کرتی ہے۔ ٹائپ کرنے سے سیریز کا نام ہر جگہ بدل جاتا ہے: اس کے سیریز کارڈ میں، اسے ڈرا کرنے والی ہر قطار میں اور لیجنڈ میں۔ طے شدہ نام (Depth یا کئی سیریز ہونے پر Depth N) استعمال کرنے کے لیے خالی چھوڑیں۔",
  "Name of the Depth series this row draws. Typing renames the series everywhere: its series card, every row that draws it, and the legend. The legend lists series in custom-stack order and omits series that no enabled row draws. Leave blank for the default name: Depth, or Depth N when there are several series.": "گہرائی کی اس سیریز کا نام جسے یہ قطار ڈرا کرتی ہے۔ ٹائپ کرنے سے سیریز کا نام ہر جگہ بدل جاتا ہے: اس کے سیریز کارڈ میں، اسے ڈرا کرنے والی ہر قطار میں اور لیجنڈ میں۔ لیجنڈ سیریز کو حسب ضرورت اسٹیک کی ترتیب میں درج کرتا ہے اور وہ سیریز خارج کر دیتا ہے جنہیں کوئی فعال قطار ڈرا نہیں کرتی۔ طے شدہ نام (Depth یا کئی سیریز ہونے پر Depth N) استعمال کرنے کے لیے خالی چھوڑیں۔",
  "Name of this Depth series in the legend. The legend label field of every Depth row that draws this series edits the same name. Leave blank for the default name: Depth, or Depth N when there are several series.": "لیجنڈ میں گہرائی کی اس سیریز کا نام۔ گہرائی کی جو بھی قطار اس سیریز کو ڈرا کرتی ہے، اس کا فیلڈ “لیجنڈ لیبل” اسی نام میں ترمیم کرتا ہے۔ طے شدہ نام (Depth یا کئی سیریز ہونے پر Depth N) استعمال کرنے کے لیے خالی چھوڑیں۔",
  "Name of this row in the diagram legend. Leave blank to use the caption of its track, or else its query in words.": "خاکے کے لیجنڈ میں اس قطار کا نام۔ خالی چھوڑنے پر اس کے ٹریک کا کیپشن استعمال ہوتا ہے؛ کیپشن نہ ہو تو اس کی query کو الفاظ میں بیان کیا جاتا ہے۔",
