  "Rows above Axis are outside the circular axis; rows below Axis are inside it. Arrow buttons reorder within the current side only. Use Move outside Axis or Move inside Axis to cross the Axis.": "قطار “محور” سے اوپر کی قطاریں دائروی خاکے کے محور کے باہر اور اس سے نیچے کی قطاریں اس کے اندر ہیں۔ تیر کے بٹن صرف موجودہ طرف کے اندر ترتیب بدلتے ہیں۔ محور کو پار کرنے کے لیے مینو آئٹم “محور سے باہر منتقل کریں” یا “محور کے اندر منتقل کریں” استعمال کریں۔",
  "Rows before Axis render above it; rows after Axis render below it. A Depth slot selects one global series and does not control vertical order. A record without a Depth TSV for that series does not draw it, but its space in the stack stays reserved.": "قطار “محور” سے پہلے کی قطاریں اس کے اوپر اور اس کے بعد کی قطاریں اس کے نیچے ڈرا ہوتی ہیں۔ گہرائی کا سلاٹ تمام ریکارڈوں کے لیے مشترک ایک سیریز چنتا ہے اور عمودی ترتیب کو کنٹرول نہیں کرتا۔ جس ریکارڈ میں اس سیریز کی گہرائی TSV فائل نہ ہو وہ اسے ڈرا نہیں کرتا، مگر اسٹیک میں اس کی جگہ مختص رہتی ہے۔",
