  "Rules are evaluated from top to bottom. Off hides the feature and leaves it out of protein search; Leave out of protein search keeps its visibility and leaves it out of protein search.": "قواعد اوپر سے نیچے کی طرف جانچے جاتے ہیں۔ آپشن “آف” فیچر کو چھپاتا ہے اور اسے پروٹین تلاش سے خارج کر دیتا ہے؛ آپشن “پروٹین تلاش سے خارج کریں” اس کی نمائش برقرار رکھتا ہے اور اسے پروٹین تلاش سے خارج کر دیتا ہے۔",
