  "Running {program} comparisons for the circular diagram: {completed}/{total} jobs complete": "دائروی خاکے کے لیے {program} موازنے چل رہے ہیں: {total} میں سے {completed} جاب مکمل",
  "SPECIFIC RULES": "مخصوص قواعد",
  "SVG ID": "SVG میں ID",
  "SVG and Interactive SVG exports carry the characters they use of this font, so they show it on computers without it. Fonts whose license forbids embedding are not embedded. Turned off, the SVG files keep only the font name. PNG export always draws this font, whatever this setting and the font's license. PDF export embeds this font whatever this setting; a font whose license forbids embedding is drawn in the nearest Liberation font.": "برآمد شدہ SVG اور انٹرایکٹو SVG فائلیں اس فونٹ کے وہ حروف شامل رکھتی ہیں جو وہ استعمال کرتی ہیں، تاکہ وہ ان کمپیوٹروں پر بھی اسی طرح دکھائی دیں جن میں یہ فونٹ نہیں ہے۔ جن فونٹوں کا لائسنس ایمبیڈ کرنے سے روکتا ہے وہ ایمبیڈ نہیں کیے جاتے۔ آف کرنے پر SVG فائلیں صرف فونٹ کا نام رکھتی ہیں۔ PNG برآمد ہمیشہ یہی فونٹ استعمال کرتی ہے، اس سیٹنگ اور فونٹ کے لائسنس سے قطع نظر۔ PDF برآمد اس سیٹنگ سے قطع نظر یہ فونٹ ایمبیڈ کرتی ہے؛ جس فونٹ کا لائسنس ایمبیڈ کرنے سے روکتا ہے وہ قریب ترین Liberation فونٹ میں ڈرا ہوتا ہے۔",
