  "Save": "محفوظ کریں",
  "Save Raw LOSAT TSV": "خام LOSAT TSV فائل محفوظ کریں",
  "Save Raw LOSAT TSV for #{from} to #{to}": "#{from} سے #{to} کی طرف خام LOSAT TSV فائل محفوظ کریں",
  "Save Session": "سیشن محفوظ کریں",
  "Save Session afterwards writes the current format. The file itself is not changed.": "اس کے بعد بٹن “سیشن محفوظ کریں” سے موجودہ فارمیٹ لکھا جاتا ہے۔ فائل خود تبدیل نہیں ہوتی۔",
  "Save Session needs current feature metadata for the loaded Result. Generate once, then Save Session.": "بٹن “سیشن محفوظ کریں” کو لوڈ کیے گئے نتیجے کے لیے موجودہ فیچر میٹا ڈیٹا درکار ہے۔ ایک بار خاکہ بنائیں، پھر بٹن “سیشن محفوظ کریں” پر کلک کریں۔",
  "Save Session stores the current Result and settings draft. The SVG, Interactive SVG, PNG, and PDF buttons download the current Result. Neither applies pending settings.": "بٹن “سیشن محفوظ کریں” موجودہ نتیجہ اور ترتیبات کا مسودہ محفوظ کرتا ہے۔ بٹن “SVG”، “انٹرایکٹو SVG”، “PNG” اور “PDF” موجودہ نتیجہ ڈاؤن لوڈ کرتے ہیں۔ دونوں میں سے کوئی بھی زیر التوا ترتیبات کو لاگو نہیں کرتا۔",
  "Save stores the current Result and generation settings draft. It does not Generate.": "بٹن “محفوظ کریں” موجودہ نتیجہ اور بنانے کی ترتیبات کا مسودہ محفوظ کرتا ہے۔ اس سے خاکہ نہیں بنتا۔",
  "Save the current Result and settings draft without generating": "بنائے بغیر موجودہ نتیجہ اور ترتیبات کا مسودہ محفوظ کریں",
  "Saved Circular diagram: its settings ({path}) could not be read; that diagram and its Results are left out.": "محفوظ شدہ دائروی خاکہ: اس کی ترتیبات ({path}) پڑھی نہیں جا سکیں؛ وہ خاکہ اور اس کے نتائج خارج کر دیے گئے۔",
  "Saved Linear diagram: its settings ({path}) could not be read; that diagram and its Results are left out.": "محفوظ شدہ لکیری خاکہ: اس کی ترتیبات ({path}) پڑھی نہیں جا سکیں؛ وہ خاکہ اور اس کے نتائج خارج کر دیے گئے۔",
  "Saved alignment needs repair.": "محفوظ شدہ سیدھ کی مرمت درکار ہے۔",
  "Saved comparison needs a decision": "محفوظ شدہ موازنے پر فیصلہ درکار ہے",
  "Saved comparison preserved as read-only": "محفوظ شدہ موازنہ صرف پڑھنے کے لیے برقرار رکھا گیا",
  "Saved diagram: the LOSAT results saved for its protein comparison ({path}) could not be read. Click Generate to run the comparison again before you edit the diagram.": "محفوظ شدہ خاکہ: اس کے پروٹین موازنے کے لیے محفوظ کیے گئے LOSAT نتائج ({path}) پڑھے نہیں جا سکے۔ خاکے میں ترمیم کرنے سے پہلے موازنہ دوبارہ چلانے کے لیے بٹن “بنائیں” پر کلک کریں۔",
  "Saved diagram: the settings of the saved diagram ({path}) could not be read. The file loads as settings only; the saved Results, the GenBank, GFF and FASTA inputs, the feature list and the caches are left out.": "محفوظ شدہ خاکہ: محفوظ شدہ خاکے کی ترتیبات ({path}) پڑھی نہیں جا سکیں۔ فائل صرف ترتیبات کے طور پر لوڈ ہوتی ہے؛ محفوظ شدہ نتائج، GenBank، GFF اور FASTA ان پٹ، فیچر فہرست اور کیش خارج کر دیے گئے۔",
  "Saved other diagram: its settings ({path}) could not be read; that diagram and its Results are left out.": "محفوظ شدہ دوسرا خاکہ: اس کی ترتیبات ({path}) پڑھی نہیں جا سکیں؛ وہ خاکہ اور اس کے نتائج خارج کر دیے گئے۔",
  "Saving session. Retry after saving finishes.": "سیشن محفوظ کیا جا رہا ہے۔ محفوظ ہونے کے بعد دوبارہ کوشش کریں۔",
