  "Search the records of the shown drawing, as last generated, for query sequences with LOSAT. Each search adds an annotation set of its hits, drawn at once. The queries and settings here are not saved in the Session.": "دکھائی گئی ڈرائنگ کے ریکارڈوں میں، ان کی آخری بار بنائی گئی صورت کے مطابق، LOSAT کے ذریعے query سیکوئنس تلاش کریں۔ ہر تلاش اپنے hit کی تشریحات کا ایک سیٹ شامل کرتی ہے جو فوراً ڈرا ہو جاتا ہے۔ یہاں کے query اور ترتیبات سیشن میں محفوظ نہیں ہوتے۔",
  "Search with a JavaScript regular expression; upper and lower case match alike.": "ریگولر ایکسپریشن (JavaScript) سے تلاش کریں؛ بڑے اور چھوٹے حروف میں فرق نہیں کیا جاتا۔",
  "Searching other files...": "دیگر فائلوں میں تلاش ہو رہی ہے…",
  "Searching sequences...": "سیکوئنسوں کی تلاش ہو رہی ہے…",
  "Select Hide GC Content, or reduce GC Content Width (with Custom Track Slots on, the row width).": "چیک باکس “GC کی مقدار چھپائیں” منتخب کریں یا فیلڈ “ٹریک ‘GC کی مقدار’ کی چوڑائی” کی قدر کم کریں (جب “حسب ضرورت ٹریک سلاٹ” آن ہوں تو قطار کی چوڑائی کم کریں)۔",
  "Select Hide GC Skew, or reduce GC Skew Width (with Custom Track Slots on, the row width).": "چیک باکس “GC skew چھپائیں” منتخب کریں یا فیلڈ “ٹریک ‘GC skew’ کی چوڑائی” کی قدر کم کریں (جب “حسب ضرورت ٹریک سلاٹ” آن ہوں تو قطار کی چوڑائی کم کریں)۔",
  "Select a row to edit its label or open its details.": "اس کے لیبل میں ترمیم کرنے یا اس کی تفصیلات کھولنے کے لیے قطار منتخب کریں۔",
  "Select all": "سب منتخب کریں",
  "Select an anchor or Skip this record first.": "پہلے کوئی اینکر منتخب کریں یا بٹن “اس ریکارڈ کو چھوڑ دیں” پر کلک کریں۔",
  "Select an available series or delete this slot.": "دستیاب سیریز منتخب کریں یا اس سلاٹ کو حذف کریں۔",
  "Select an eligible enabled anchor for an annotation track whose placement is Overlay anchor (Circular) or On axis (Linear).": "جس تشریحی ٹریک کی جگہ کا آپشن “اینکر پر” (دائروی) یا “محور پر” (لکیری) ہو، اس کے لیے کوئی اہل فعال اینکر منتخب کریں۔",
  "Select an exact reference record and feature before aligning.": "سیدھ میں لانے سے پہلے کوئی عین ریفرنس ریکارڈ اور فیچر منتخب کریں۔",
  "Select an existing Depth TSV or remove the slot.": "گہرائی کی پہلے سے موجود TSV فائل منتخب کریں یا سلاٹ ہٹائیں۔",
  "Select an existing annotation set.": "پہلے سے موجود تشریحات کا سیٹ منتخب کریں۔",
