  "Select one record to edit crop, orientation, and title lines.": "تراش، رخ اور عنوان کی سطروں میں ترمیم کے لیے ایک ریکارڈ منتخب کریں۔",
  "Select preset...": "پری سیٹ چنیں…",
  "Select region": "خطہ منتخب کریں",
