  "Select the record to draw as one Circular diagram. Leave this on All records to draw each record as its own diagram.": "وہ ریکارڈ منتخب کریں جسے ایک دائروی خاکے کے طور پر ڈرا کرنا ہے۔ ہر ریکارڈ کو الگ خاکے کے طور پر ڈرا کرنے کے لیے اس فیلڈ کو آپشن “تمام ریکارڈ” پر رہنے دیں۔",
  "Select which feature types to draw.": "منتخب کریں کہ فیچر کی کون سی اقسام ڈرا کی جائیں۔",
  "Select {count} feature": "{count} فیچر منتخب کریں",
