  "Select {label}, {coordinates} for {record}": "ریکارڈ {record} کے لیے {label}، {coordinates} منتخب کریں",
  "Select {label}, {coordinates}, strand {strand} for {record}": "ریکارڈ {record} کے لیے منتخب کریں: {label}، {coordinates}، اسٹرینڈ {strand}",
  "Selected LOSAT comparisons require LOSATP Pairwise mode. For Similarity groups or Collinear blocks, choose Run LOSAT for all adjacent pairs.": "منتخب LOSAT موازنوں کے لیے LOSATP کا موڈ “جوڑی وار مطابقتیں” ضروری ہے۔ موڈ “مماثلت کے گروپ” یا موڈ “collinear بلاک” کے لیے آپشن “تمام ملحقہ جوڑیوں کے لیے LOSAT چلائیں” چنیں۔",
  "Selected by user": "صارف کا منتخب کردہ",
  "Selected comparisons cannot contain the same directed pair more than once.": "منتخب موازنوں میں ایک ہی سمت دار جوڑی ایک سے زیادہ بار نہیں ہو سکتی۔",
