  "Sequence content is undefined: a record has no sequence after ORIGIN. Use a GenBank/DDBJ file that includes the sequence.": "سیکوئنس غیر متعین ہے: ایک ریکارڈ میں ORIGIN کے بعد کوئی سیکوئنس نہیں ہے۔ ایسی GenBank/DDBJ فائل استعمال کریں جس میں سیکوئنس شامل ہو۔",
