  "Session": "سیشن",
  "Session file: the feature list and the Legend and stroke edits of the saved diagram ({path}) could not be read and are left out.": "سیشن فائل: محفوظ شدہ خاکے کی فیچر فہرست اور لیجنڈ اور آؤٹ لائن کی ترامیم ({path}) پڑھی نہیں جا سکیں اور خارج کر دی گئیں۔",
  "Session file: the field {items} could not be read and was left out.": "سیشن فائل: فیلڈ {items} پڑھا نہیں جا سکا اور خارج کر دیا گیا۔",
  "Session file: the fields {items} could not be read and were left out.": "سیشن فائل: فیلڈ {items} پڑھے نہیں جا سکے اور خارج کر دیے گئے۔",
  "Session file: the saved Results ({path}) could not be read and are left out.": "سیشن فائل: محفوظ شدہ نتائج ({path}) پڑھے نہیں جا سکے اور خارج کر دیے گئے۔",
  "Session file: the saved diagram of the other mode ({path}) could not be read and is left out.": "سیشن فائل: دوسرے موڈ کا محفوظ شدہ خاکہ ({path}) پڑھا نہیں جا سکا اور خارج کر دیا گیا۔",
  "Session file: the settings of both drawings ({path}) could not be read and are left out.": "سیشن فائل: دونوں ڈرائنگوں کی ترتیبات ({path}) پڑھی نہیں جا سکیں اور خارج کر دی گئیں۔",
  "Session file: the settings of the Circular drawing ({path}) could not be read and are left out.": "سیشن فائل: دائروی ڈرائنگ کی ترتیبات ({path}) پڑھی نہیں جا سکیں اور خارج کر دی گئیں۔",
  "Session file: the settings of the Linear drawing ({path}) could not be read and are left out.": "سیشن فائل: لکیری ڈرائنگ کی ترتیبات ({path}) پڑھی نہیں جا سکیں اور خارج کر دی گئیں۔",
  "Session file: the stored input files ({path}) could not be read and are left out.": "سیشن فائل: محفوظ کی گئی ان پٹ فائلیں ({path}) پڑھی نہیں جا سکیں اور خارج کر دی گئیں۔",
  "Session file: {path} could not be read and is left out.": "سیشن فائل: سیشن کا حصہ {path} پڑھا نہیں جا سکا اور خارج کر دیا گیا۔",
  "Session loaded.": "سیشن لوڈ ہو گیا۔",
  "Session loaded: {file}.": "سیشن لوڈ ہو گیا: {file}۔",
  "Session not loaded": "سیشن لوڈ نہیں ہوا",
  "Session render requests require at least one record.": "سیشن کی رینڈر درخواستوں کے لیے کم از کم ایک ریکارڈ ضروری ہے۔",
  "Session saved: {file}.": "سیشن محفوظ ہو گیا: {file}۔",
  "Session table: {table}.": "سیشن جدول: {table}۔",
  "Session title": "سیشن کا عنوان",
  "Session version {version} is newer than this gbdraw supports ({latest}).": "سیشن ورژن {version} اس تازہ ترین سیشن ورژن ({latest}) سے نیا ہے جسے gbdraw کا یہ ورژن معاونت دیتا ہے۔",
  "Set Figure height to at least {minimum}, or leave it empty (Auto).": "فیلڈ “شکل کی اونچائی” میں کم از کم {minimum} درج کریں یا خودکار قدر کے لیے اسے خالی چھوڑیں۔",
  "Set Figure width to at least {minimum}, or leave it empty (Auto).": "فیلڈ “شکل کی چوڑائی” میں کم از کم {minimum} درج کریں یا خودکار قدر کے لیے اسے خالی چھوڑیں۔",
  "Set Figure width to at least {minimum}, place the Legend at the top or bottom, or leave it empty (Auto).": "فیلڈ “شکل کی چوڑائی” میں کم از کم {minimum} درج کریں، لیجنڈ کو اوپر یا نیچے رکھیں یا خودکار قدر کے لیے فیلڈ “شکل کی چوڑائی” خالی چھوڑیں۔",
  "Set Reverse complement from the comparisons: changed {records}. Generate to draw the new orientation.": "موازنوں سے ریورس کمپلیمنٹ سیٹ کیا گیا: تبدیل شدہ ریکارڈ: {records}۔ نیا رخ ڈرا کرنے کے لیے خاکہ دوبارہ بنائیں۔",
  "Set all adjacent comparisons": "تمام ملحقہ موازنے سیٹ کریں",
  "Set circular label placement. 'Out' places labels outside; 'Both' places labels outside and inside. With horizontal inner labels, implicit GC content and GC skew tracks are hidden to avoid overlap.": "دائروی خاکے کے لیبلوں کی جگہ مقرر کریں۔ آپشن “باہر” لیبلوں کو باہر رکھتا ہے؛ آپشن “دونوں (باہر + اندر)” لیبلوں کو باہر اور اندر رکھتا ہے۔ افقی اندرونی لیبلوں کے ساتھ، اوورلیپ سے بچنے کے لیے GC کی مقدار اور GC skew کے خود بخود شامل ہونے والے ٹریک چھپا دیے جاتے ہیں۔",
  "Set id \"{text}\" is used by another set, so it was saved as \"{stored}\".": "سیٹ کی ID “{text}” دوسرے سیٹ میں استعمال ہو رہی ہے، اس لیے یہ ID “{stored}” کے طور پر محفوظ کی گئی۔",
  "Set id cannot be empty, so it was saved as \"{stored}\".": "سیٹ کی ID خالی نہیں ہو سکتی، اس لیے یہ ID “{stored}” کے طور پر محفوظ کی گئی۔",
  "Set legend label": "سیٹ کا لیجنڈ لیبل",
