  "Set that feature's Feature placement to Auto or Main, or use split feature lanes (Track Preset Middle).": "اس فیچر کے لیے فیلڈ “فیچر کی جگہ” کو آپشن “خودکار” یا “مرکزی” پر سیٹ کریں یا الگ کی گئی فیچر لینیں استعمال کریں (ٹریک پری سیٹ کی قدر Middle)۔",
  "Set the ring name, color, and default order for each pairwise comparison source. Custom Track Slots can override the radial track order.": "ہر جوڑی وار موازنے کے ماخذ کے لیے حلقے کا نام، رنگ اور طے شدہ ترتیب سیٹ کریں۔ ٹریکوں کی ریڈیل ترتیب کو حسب ضرورت ٹریک سلاٹ اوور رائیڈ کر سکتے ہیں۔",
  "Set the translation table for each sequence in its {options}.": "ہر سیکوئنس کے لیے ٹرانسلیشن ٹیبل متعلقہ حصے {options} میں سیٹ کریں۔",
  "Set up a comparison in the Comparison panel, or choose Clear comparison, then Generate again.": "سیکشن “موازنہ” میں موازنہ ترتیب دیں یا بٹن “موازنہ صاف کریں” چنیں، پھر خاکہ دوبارہ بنائیں۔",
  "Sets the {type} default color ({type} features without their own color or rule, also hidden ones).": "فیچر {type} کا طے شدہ رنگ متعین کیا جاتا ہے (قسم {type} کے ان فیچروں کے لیے جن کا اپنا رنگ یا قاعدہ نہیں ہے، چھپے ہوئے فیچر بھی شامل)۔",
