  "Settings: the value \"{stored}\" ({path}) cannot be used; its default is used.": "ترتیبات: قدر “{stored}” ({path}) استعمال نہیں کی جا سکتی؛ اس کی طے شدہ قدر استعمال کی جاتی ہے۔",
