  "Settings: the value of {path} cannot be used; the drawing keeps its current value.": "ترتیبات: فیلڈ {path} کی قدر استعمال نہیں کی جا سکتی؛ ڈرائنگ اپنی موجودہ قدر برقرار رکھتی ہے۔",
