  "Settings: {path} names a file or record this Session does not hold; it is left out.": "ترتیبات: فیلڈ {path} ایسی فائل یا ایسے ریکارڈ کا حوالہ دیتا ہے جو اس سیشن میں موجود نہیں؛ اس فیلڈ کو خارج کر دیا گیا ہے۔",
  "Several candidates": "کئی امیدوار",
