  "Similarity groups and Collinear blocks compare every adjacent pair with LOSAT.": "موڈ “مماثلت کے گروپ” اور “collinear بلاک” LOSAT کے ذریعے ہر ملحقہ جوڑی کا موازنہ کرتے ہیں۔",
  "Similarity groups appear after a Linear comparison with Similarity groups turned on.": "موڈ “مماثلت کے گروپ” کے ساتھ لکیری موازنہ بنانے کے بعد مماثلت کے گروپ ظاہر ہوتے ہیں۔",
  "Similarity groups: {count} description edit ({path}) names a group the saved Result does not have and was dropped.": "مماثلت کے گروپ: تفصیل کی {count} ترمیم ({path}) ایسے گروپ کا حوالہ دیتی ہے جو محفوظ شدہ نتیجے میں موجود نہیں، اس لیے یہ ترمیم خارج کر دی گئی۔",
  "Similarity groups: {count} description edits ({path}) name a group the saved Result does not have and were dropped.": "مماثلت کے گروپ: تفصیل کی {count} ترامیم ({path}) ایسے گروپ کا حوالہ دیتی ہیں جو محفوظ شدہ نتیجے میں موجود نہیں، اس لیے یہ ترامیم خارج کر دی گئیں۔",
  "Similarity groups: {count} name edit ({path}) names a group the saved Result does not have and was dropped.": "مماثلت کے گروپ: نام کی {count} ترمیم ({path}) ایسے گروپ کا حوالہ دیتی ہے جو محفوظ شدہ نتیجے میں موجود نہیں، اس لیے یہ ترمیم خارج کر دی گئی۔",
  "Similarity groups: {count} name edits ({path}) name a group the saved Result does not have and were dropped.": "مماثلت کے گروپ: نام کی {count} ترامیم ({path}) ایسے گروپ کا حوالہ دیتی ہیں جو محفوظ شدہ نتیجے میں موجود نہیں، اس لیے یہ ترامیم خارج کر دی گئیں۔",
