  "Simple mode only. Above places features above the axis, Features on axis centers them on it, and Below places them below it. Use Reset to copy this choice into the custom stack.": "صرف سادہ موڈ۔ آپشن “اوپر” فیچروں کو محور کے اوپر، آپشن “فیچر محور پر” انہیں محور پر مرکز میں، اور آپشن “نیچے” انہیں محور کے نیچے رکھتا ہے۔ اس انتخاب کو حسب ضرورت اسٹیک میں کاپی کرنے کے لیے بٹن “ری سیٹ کریں” استعمال کریں۔",
  "Simple mode only. Display a GC content track; use Reset to copy it into the custom stack.": "صرف سادہ موڈ۔ GC کی مقدار کا ٹریک دکھائیں؛ اسے حسب ضرورت اسٹیک میں کاپی کرنے کے لیے بٹن “ری سیٹ کریں” استعمال کریں۔",
  "Simple mode only. Display a GC skew track; use Reset to copy it into the custom stack.": "صرف سادہ موڈ۔ GC skew کا ٹریک دکھائیں؛ اسے حسب ضرورت اسٹیک میں کاپی کرنے کے لیے بٹن “ری سیٹ کریں” استعمال کریں۔",
  "Simple mode only. Display depth coverage tracks from uploaded TSV files; use Reset to copy them into the custom stack.": "صرف سادہ موڈ۔ اپ لوڈ شدہ TSV فائلوں سے گہرائی کے ٹریک دکھائیں؛ انہیں حسب ضرورت اسٹیک میں کاپی کرنے کے لیے بٹن “ری سیٹ کریں” استعمال کریں۔",
