  "Step size for depth aggregation. Blank: a tenth of the GC step, at least 1 bp.": "گہرائی کی ایگریگیشن کے لیے قدم کا سائز۔ خالی ہو تو GC قدم کا دسواں حصہ، لیکن 1 bp سے کم نہیں۔",
  "Str.": "اسٹرینڈ",
