  "Strand": "اسٹرینڈ",
  "Strand: neighboring anchors of a block follow its strand orientation and the gene order. Gene order: they follow the gene order only.": "آپشن “اسٹرینڈ” میں بلاک کے پڑوسی اینکر اس کے اسٹرینڈ کے رخ اور جین کی ترتیب دونوں کی پیروی کرتے ہیں۔ آپشن “جین کی ترتیب” میں وہ صرف جین کی ترتیب کی پیروی کرتے ہیں۔",
  "Stretch the overlay from its anchor to this slot, over every slot between them (to_slot). None: the overlay's own band.": "اوور لے کو اس کے اینکر سے اس سلاٹ تک، درمیان کے ہر سلاٹ پر، پھیلائیں (to_slot)۔ کوئی نہیں: اوور لے کا اپنا بینڈ۔",
