  "Suggest a translation fix": "ترجمے کی درستی تجویز کریں",
  "Summary": "خلاصہ",
  "Supply GenBank input or matching GFF3 and FASTA inputs.": "ان پٹ کے طور پر GenBank فراہم کریں یا مطابقت رکھنے والے GFF3 اور FASTA ان پٹ فراہم کریں۔",
  "Supply a comparison sequence file (FASTA, GenBank, or DDBJ) or BLAST outfmt 6/7 as required.": "ضرورت کے مطابق موازنے کی سیکوئنس فائل (FASTA، GenBank یا DDBJ) یا BLAST outfmt 6/7 فراہم کریں۔",
  "Supply a matching FASTA input for each GFF3 input.": "ہر GFF3 ان پٹ کے لیے مطابقت رکھنے والا FASTA ان پٹ فراہم کریں۔",
  "Supply at least three tab-separated columns.": "کم از کم تین کالم فراہم کریں، جو Tab سے الگ کیے گئے ہوں۔",
  "Supply both region endpoints or leave both empty.": "خطے کا آغاز اور اختتام دونوں فراہم کریں یا دونوں خالی چھوڑیں۔",
  "Supply four or five tab-separated columns.": "چار یا پانچ کالم فراہم کریں، جو Tab سے الگ کیے گئے ہوں۔",
  "Supply the required value.": "ضروری قدر فراہم کریں۔",
