  "TLOSATX gencode for sequence {n}": "سیکوئنس {n} کے لیے TLOSATX کا جینیاتی کوڈ",
  "TSV file of rules: feature type, qualifier, regular expression, color, and optional legend name.": "فائل TSV برائے قواعد: فیچر کی قسم، qualifier، ریگولر ایکسپریشن، رنگ اور اختیاری لیجنڈ کا نام۔",
  "Tab-separated value (TSV) file of feature type and color. Feature types not listed keep the selected palette colors.": "فائل TSV (Tab سے الگ کی گئی قدریں) جس میں فیچر کی قسم اور رنگ ہوں۔ فیچر کی جو اقسام درج نہیں ہیں وہ منتخب پیلیٹ کے رنگ برقرار رکھتی ہیں۔",
