  "This row keeps '{param}' from another renderer.": "اس قطار میں دوسرے رینڈرر کا پیرامیٹر “{param}” برقرار ہے۔",
  "This row must be an object.": "یہ قطار آبجیکٹ ہونی چاہیے۔",
