  "This row's side conflicts with the Axis boundary.": "اس قطار میں درج طرف محور کی حد سے متصادم ہے۔",
  "This tool is provided \"as is\" without warranty of any kind.": "یہ ٹول بغیر کسی قسم کی ضمانت کے “جیسا ہے” کی بنیاد پر فراہم کیا جاتا ہے۔",
  "Threaded": "تھریڈڈ",
