  "Threaded LOSAT execution is unavailable in this browser environment. Select Serial or Auto execution, then click Search again.": "اس براؤزر ماحول میں ٹول LOSAT کا تھریڈڈ عمل درآمد دستیاب نہیں ہے۔ عمل درآمد کے لیے آپشن “ترتیب وار” یا آپشن “خودکار” منتخب کریں، پھر دوبارہ بٹن “تلاش کریں” پر کلک کریں۔",
