  "Track stack: the Depth row \"{label}\" ({path}) names a Depth series its drawing does not have; the row is turned off and no longer names that series.": "ٹریک اسٹیک: گہرائی کی قطار “{label}” ({path}) گہرائی کی ایسی سیریز کا حوالہ دیتی ہے جو اس کی ڈرائنگ میں موجود نہیں؛ قطار آف کر دی گئی ہے اور اب اس سیریز کا حوالہ نہیں دیتی۔",
