  "Translation table for the displayed circular sequence used by TLOSATX.": "دائروی خاکے میں دکھائی گئی سیکوئنس کا ٹرانسلیشن ٹیبل، جو TLOSATX کے لیے استعمال ہوتا ہے۔",
  "Tuckin": "Tuckin",
  "Turn Normalize Record Lengths off or assign each record to a separate Linear row.": "چیک باکس “ریکارڈوں کی لمبائیاں نارملائز کریں” سے نشان ہٹائیں یا لکیری خاکے میں ہر ریکارڈ کو الگ قطار تفویض کریں۔",
  "Turn off Embed font in exported SVG in Font to export without the font, or choose another font.": "فونٹ کے بغیر برآمد کرنے کے لیے سیکشن “فونٹ” میں چیک باکس “برآمد شدہ SVG میں فونٹ ایمبیڈ کریں” سے نشان ہٹائیں یا کوئی اور فونٹ چنیں۔",
  "Turn off track rows": "ٹریک قطاریں آف کریں",
  "Turn on Layout edit to move a legend, title, or Linear scale. When off, drag to pan. Use the Layout edit button with click, tap, Space, or Enter.": "لیجنڈ، عنوان یا لکیری پیمانہ منتقل کرنے کے لیے موڈ “لے آؤٹ ترمیم” آن کریں۔ آف ہونے پر منظر سرکانے کے لیے کھینچیں۔ بٹن “لے آؤٹ ترمیم” کو کلک، ٹیپ، Space یا Enter کے ذریعے استعمال کریں۔",
  "Turn on Layout edit to move this item": "اس آئٹم کو منتقل کرنے کے لیے موڈ “لے آؤٹ ترمیم” آن کریں",
  "Turn on at least one record to draw.": "ڈرا کرنے کے لیے کم از کم ایک ریکارڈ آن کریں۔",
  "Turn on to move a legend, title, or Linear scale. While off, dragging pans the view.": "لیجنڈ، عنوان یا لکیری پیمانہ منتقل کرنے کے لیے آن کریں۔ آف ہونے پر کھینچنے سے منظر سرکتا ہے۔",
  "Two region annotations overlap in the same lane of the annotation table, counting their labels and padding. Give one of them another lane in Region Annotations, or set the Annotations row's Overflow behavior to Compress or Clip in Custom Track Slots (Use custom stack).": "خطے کی دو تشریحات تشریحات کے جدول کی ایک ہی لین میں اپنے لیبل اور پیڈنگ سمیت اوورلیپ ہوتی ہیں۔ سیکشن “خطوں کی تشریحات” میں ان میں سے ایک کو کوئی اور لین دیں یا سیکشن “حسب ضرورت ٹریک سلاٹ” میں چیک باکس “حسب ضرورت اسٹیک استعمال کریں” منتخب کر کے قطار “تشریحات” کے فیلڈ “اوور فلو کا رویہ” کو آپشن “سکیڑنا” یا “کلپ” پر سیٹ کریں۔",
  "Two windows of the record overlap at {span}.": "ریکارڈ کی دو ونڈو {span} پر اوورلیپ ہوتی ہیں۔",
  "Unavailable File": "دستیاب نہ ہونے والی فائل",
  "Unavailable record": "دستیاب نہ ہونے والا ریکارڈ",
  "Unbounded": "لامحدود",
  "Unchanged": "تبدیلی نہیں",
  "Unchanged: {reason}": "تبدیلی نہیں: {reason}",
  "Underlay": "انڈر لے",
  "Underline": "انڈر لائن",
  "Underline draws a line under each horizontal label with a leader, joined to its leader; a turned label gets none. None draws no line.": "آپشن “انڈر لائن” لیڈر لائن والے ہر افقی لیبل کے نیچے لکیر کھینچتا ہے، جو اس کی لیڈر لائن سے جڑی ہوتی ہے؛ گھمائے گئے لیبل کو کوئی لکیر نہیں ملتی۔ آپشن “کوئی نہیں” کوئی لکیر نہیں کھینچتا۔",
  "Undo": "کالعدم کریں",
  "Undo or Redo in progress. Retry after it finishes.": "کالعدم کرنے یا دوبارہ کرنے کا عمل جاری ہے۔ اس کے مکمل ہونے کے بعد دوبارہ کوشش کریں۔",
  "Undo restores the drawing": "کالعدم کرنے سے ڈرائنگ بحال ہو جاتی ہے",
  "Undo restores them": "کالعدم کرنے سے وہ بحال ہو جاتی ہیں",
  "Undo the latest Align.": "آخری “سیدھ میں لائیں” کارروائی کو کالعدم کریں۔",
